INSERT INTO `register_temp_bk` VALUES (3183,'2026-01-14 12:45:12','2026-01-14 13:18:05','anonymous',NULL,NULL,'รับทราบ','นาย',NULL,'ชาคริต ','','Chakrit','','','','ลีนุตพงษ์','','Leenutaphong','ชาย','1989-02-27','O','1100900429582','2031-02-26','พุทธ','Chakrit_lee',NULL,NULL,'ไม่มี','ไม่มี','c.leenutaphong@gmail.com','0819888877','กัลยกร อัคคเตชภาคิน','0936916642','12/1-4','รองเมือง 5',NULL,NULL,'รองเมือง','รองเมือง','ปทุมวัน','กรุงเทพ','10330','ที่อยู่อื่น ๆ (โปรดระบุ)','264','พัฒนาการ 38 ',NULL,NULL,'พัฒนาการ','สวนหลวง','สวนหลวง','กรุงเทพ','10250.0','ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','5804025208','ขอต่ออายุใบอนุญาตเป็น ตัวแทนหรือนายหน้า ประกันวินา','2015-10-09','2028-10-08','ภาค 6 (ภาคกรุงเทพฯ)',NULL,NULL,NULL,NULL,NULL,'วิภาวดี',NULL,NULL,'การบริหารการลงทุนของบริษัทประกันภัย;การประกันภัยความรับผิดตามกฏหมาย;เสนอขายถูกหลักประกันภัยเติบโต;การจ่ายค่าสินไหมทดแทนประกันวินาศภัย;การวางแผนภาษีสำหรับตัวแทนและนายหน้าประกันภัย;การประกันความเสี่ยงภัยทรัพย์สิน;การประกันภัยต่อ;การพิจารณารับประกันภัยรถยนต์;กฏหมายและวิธีปฏิบัติที่เกี่ยวข้องกับธุรกิจประกันภัย;ความเสี่ยงต่อความรับผิดในฐานะตัวแทน/นายหน้าประกันภัย;หลักกฏหมายและวิธีการปฏิบัติในการประกันภัยสินค้าทางทะเล;จรรยาบรรณและศีลธรรมของตัวแทน/นายหน้าประกันภัย;พ.ร.บ.การทวงถามหนี้;กฎหมายเบื้องต้นที่จำเป็นสำหรับชีวิตประจำวัน;พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล;ประมวลกฎหมายแพ่งและพาณิชย์ว่าด้วยละเมิด;รู้จักประกันภัยสุขภาพ;กฎหมายและหลักการประกันภัยคุ้มครองผู้ประสบภัยจากรถ (พ.ร.บ.)','นายหน้า',NULL,NULL,NULL,NULL,'ขอต่อใบอนุญาตตัวแทน/นายหน้าประกันวินาศภัย 4',NULL,NULL,NULL,'[Pillar 1] [20 พฤษภาคม 2569] : กรมธรรม์ประกันภัยรถยนต์ไฟฟ้ารวมการคุ้มครองผู้ประสบภัยจากรถ;[Pillar 1] [22 เมษายน 2569] : การกำกับดูแลบริษัทประกันภัยตามระดับความเสี่ยง;[Pillar 1] [22 เมษายน 2569] : การจัดการสินไหมทดแทน Non-Motor','12687','12687',10.00,'อบรบประกันภัยที่เกี่ยวกับแบตเตอรี่ไฟฟ้า/รถไฟฟ้า','ภาคกลาง;','บริษัท แอลเอ็มจี ประกันภัย จำกัด (มหาชน);บริษัท แอกซ่าประกันภัย จำกัด (มหาชน);บริษัท เอไอจี ประกันภัย (ประเทศไทย) จำกัด (มหาชน);บริษัท อลิอันซ์ อยุธยา ประกันภัย จำกัด (มหาชน);บริษัท เมืองไทยประกันภัย จำกัด (มหาชน);','ประกันภัยรถยนต์;','วิภาวดี','ผู้จําหน่ายรถบีเอ็มดับเบิลยู',NULL,NULL),(3184,'2026-01-14 13:04:00','2026-01-14 13:19:00','anonymous',NULL,NULL,'รับทราบ','นางสาว',NULL,'ตะวัน','','Tawan','','','','อุดมชัยเดช','','Udomchaidate','หญิง','1987-11-09','A','1102000876886','2030-11-08','พุทธ',NULL,NULL,NULL,NULL,NULL,'miniminijung11@hotmail.com','0806035772',NULL,NULL,'1/95','6',NULL,'แลนด์ซีโอ้ไพรด์ -คลองภนน','เลียบคลองโต๊ะใหม่','บางคูรัด','บางบัวทอง','นนทบุรี','11110','ตรงกับที่อยู่ตามทะเบียนบ้าน',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','6204037480','ขอต่ออายุใบอนุญาตเป็น ตัวแทนหรือนายหน้า ประกันวินา','2019-09-05','2027-09-04','สำนักงานใหญ่',NULL,NULL,NULL,NULL,NULL,'บางพลัด',NULL,NULL,'การกำกับดูแลบริษัทประกันภัยตามระดับความเสี่ยง				;การประกันภัยความรับผิดตามกฏหมาย;การจ่ายค่าสินไหมทดแทนประกันวินาศภัย;การพิจารณารับประกันภัยรถยนต์;กฏหมายและวิธีปฏิบัติที่เกี่ยวข้องกับธุรกิจประกันภัย;ความเสี่ยงต่อความรับผิดในฐานะตัวแทน/นายหน้าประกันภัย;หลักกฏหมายและวิธีการปฏิบัติในการประกันภัยสินค้าทางทะเล;รู้จักประกันภัยสุขภาพ;กฎหมายและหลักการประกันภัยคุ้มครองผู้ประสบภัยจากรถ (พ.ร.บ.)','นายหน้า',NULL,NULL,NULL,NULL,'ขอต่อใบอนุญาตตัวแทน/นายหน้าประกันวินาศภัย 4',NULL,NULL,NULL,NULL,'อีซี่อินชัวร์โบรกเกอร์จำกัด','04727',10.00,NULL,NULL,'บริษัท กรุงเทพประกันภัย จำกัด (มหาชน);บริษัท คุ้มภัยโตเกียวมารีนประกันภัย (ประเทศไทย) จำกัด;บริษัท เจมาร์ทประกันภัย จำกัด (มหาชน);บริษัท ชับบ์สามัคคีประกันภัย จำกัด (มหาชน);บริษัท ทิพยประกันภัย จำกัด (มหาชน);บริษัท เทเวศประกันภัย จำกัด (มหาชน);บริษัท ไทยประกันสุขภาพ จำกัด (มหาชน);บริษัท ไทยไพบูลย์ประกันภัย จำกัด (มหาชน);บริษัท ไทยเศรษฐกิจประกันภัย จำกัด (มหาชน);บริษัท ธนชาตประกันภัย จำกัด (มหาชน);บริษัท นวกิจประกันภัย จำกัด (มหาชน);บริษัท ประกันภัยไทยวิวัฒน์ จำกัด (มหาชน);บริษัท มิตรแท้ประกันภัย จำกัด (มหาชน);บริษัท เมืองไทยประกันภัย จำกัด (มหาชน);บริษัท อลิอันซ์ อยุธยา ประกันภัย จำกัด (มหาชน);บริษัท เอ็มเอสไอจี ประกันภัย (ประเทศไทย) จำกัด (มหาชน);บริษัท แอกซ่าป