--
-- Table structure for table `register_uat`
--

DROP TABLE IF EXISTS `register_uat`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `register_uat` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `pdpa_consent` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ข้าพเจ้าได้อ่านนโยบายและประกาศการคุ้มครองข้อมูลส่วนบุคคล และรับทราบ',
  `national_id` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'เลขประจำตัวประชาชน',
  `id_card_expiry` date DEFAULT NULL COMMENT 'วันบัตรหมดอายุ',
  `title_th` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'คำนำหน้าตามบัตรประชาชน',
  `title_custom` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'คำนำหน้าตามบัตรประชาชน (ระบุเอง)',
  `first_name_th` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ชื่อภาษาไทย',
  `middle_name_th` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ชื่อกลางภาษาไทย (ถ้ามี)',
  `last_name_th` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'นามสกุลภาษาไทย',
  `first_name_en` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ชื่อภาษาอังกฤษ',
  `middle_name_en` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ชื่อกลางภาษาอังกฤษ (ถ้ามี)',
  `last_name_en` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'นามสกุลภาษาอังกฤษ',
  `first_name_old_th` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ชื่อเดิมภาษาไทย (ถ้ามี)',
  `middle_name_old_th` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ชื่อกลางเดิมภาษาไทย (ถ้ามี)',
  `last_name_old_th` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'นามสกุลเดิมภาษาไทย (ถ้ามี)',
  `birth_date` date DEFAULT NULL COMMENT 'วันเกิด',
  `religion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ศาสนา',
  `gender` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'เพศ',
  `blood_group` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'กรุ๊ปเลือด',
  `phone_otp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'หมายเลขโทรศัพท์ที่รับ OTP ได้',
  `email_alt` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'eMail',
  `line_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Line ID',
  `facebook` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Facebook',
  `instagram` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Instagram',
  `food_allergy` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'คุณเคยมีประวัติแพ้อาหารหรือไม่ (โปรดระบุ)',
