INSERT INTO `register_uat_bak` VALUES (49,'รับทราบ','3669900113518','2032-10-15','3',NULL,'ชวจรรย์','','บุพนิมิตร','CHAWAJAN','','BOOPPANIMIT','','','','1978-10-16','พุทธ','หญิง','A','0817557548','chawajan@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'155/9 ม.ชวนชื่น กรีนพาร์ค',NULL,NULL,'คู้บอน 27 แยก 11','รามอินทรา ','กรุงเทพมหานคร','บางเขน','ท่าแร้ง','10230','ตรงกับที่อยู่ตามทะเบียนบ้าน',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','ขอต่ออายุใบอนุญาตเป็น ตัวแทนหรือนายหน้า ประกันวินา','5304018299','2010-09-27','2028-09-26',NULL,NULL,NULL,NULL,NULL,NULL,'สุขาภิบาล 3',NULL,'10788','นายหน้า',NULL,'ขอต่อใบอนุญาตตัวแทน/นายหน้าประกันวินาศภัย 4',NULL,NULL,NULL,NULL,NULL,NULL,'[Pillar 1] [22 เมษายน 2569] : การประกันความเสี่ยงภัยทรัพย์สิน;[Pillar 1] [22 เมษายน 2569] : การจัดการสินไหมทดแทน Non-Motor;[Pillar 1] [20 พฤษภาคม 2569] : กรมธรรม์ประกันภัยรถยนต์ไฟฟ้ารวมการคุ้มครองผู้ประสบภัยจากรถ;[Pillar 1] [20 พฤษภาคม 2569] : เสนอขายถูกหลักประกันภัยเติบโต;[Pillar 3] [20 พฤษภาคม 2569] : กฏหมายว่าด้วยการป้องกันและปราบปรามการฟอกเงินและต่อต้านการสนับสนุนทางการเงินแก่การก่อการร้าย;[Pillar 2] [10 มิถุนายน 2569] : การตลาดยุคใหม่;[Pillar 1] [10 มิถุนายน 2569] : รู้จักประกันภัยสุขภาพ;[Pillar 3] [13 พฤษภาคม 2569] : พ.ร.บ. จราจรทางบก พ.ศ.2522(แก้ไขเพิ่มเติม 2562) และ การพิจารณาคดีแพ่ง/คดีอาญาเมื่อเกิดอุบัติเหตุจราจร','สำเร็จการศึกษาตั้งแต่ระดับปริญญาโทขึ้นไป จากสถาบันอุดมศึกษาหรือสถาบันการศึกษาในต่างประเทศที่สำนักงานคณะกรรมการข้าราชการพลเรือนรับรอง;','กฏหมายและวิธีปฏิบัติที่เกี่ยวข้องกับธุรกิจประกันภัย;จรรยาบรรณและศีลธรรมของตัวแทน/นายหน้าประกันภัย;การประกันภัยต่อ;การวางแผนภาษีสำหรับตัวแทนและนายหน้าประกันภัย;การวางแผนเพื่อวัยเกษียณ;การกำกับดูแลบริษัทประกันภัยตามระดับความเสี่ยง				;การประกันภัยความรับผิดตามกฏหมาย;การพิจารณารับประกันภัยรถยนต์;พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล;การบริหารการลงทุนของบริษัทประกันภัย;การจ่ายค่าสินไหมทดแทนประกันวินาศภัย;ความเสี่ยงต่อความรับผิดในฐานะตัวแทน/นายหน้าประกันภัย;ธุรกิจประกันภัยไทยกับการเปิดเสรีประชาคมเศรษฐกิจอาเซียน;นวัตกรรมผลิตภัณฑ์ประกันวินาศภัย',NULL,'ปริญญาโท','พนง.บริษัท','สุขาภิบาล 3',16.00,'ภาคกลาง;','บริษัท คุ้มภัยโตเกียวมารีนประกันภัย (ประเทศไทย) จำกัด;','ประกันภัยรถยนต์;',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-05-25 08:48:30','2026-06-22 15:54:54','ยืนยันการสมัคร','2025-11-18 13:33:59','2025-11-18 14:32:02','anonymous',NULL,NULL,NULL,NULL,NULL),(67,'รับทราบ','3361000001069','2030-06-13','2',NULL,'กุสุมาพร','','ผ่านไกล','Kusumaporn','','Panklai','','','มุ่งเจือกลาง','1970-06-14','พุทธ','หญิง','A','0989356428','kusumaporn.p@gmail.com',NULL,NULL,NULL,NULL,NULL,'สุรัตน์ ผ่านไกล','0984614289','3','_','กมลรักษ์','บางพรม 43','บางพรม','กรุงเทพมหานคร','ตลิ่งชัน','บางพรม','10170','ตรงกับที่อยู่ตามทะเบียนบ้าน',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','ขอต่ออายุใบอนุญาตเป็น ตัวแทนหรือนายหน้า ประกันวินา','6004015492','2017-05-18','2030-05-17','ภาค 6 (ภาคกรุงเทพฯ)',NULL,NULL,NULL,NULL,NULL,'วิภาวดี',NULL,'08715','นายหน้า',NULL,'ขอต่อใบอนุญาตตัวแทน/นายหน้าประกันวินาศภัย 4',NULL,NULL,NULL,NULL,NULL,NULL,'[Pillar 1] [5 สิงหาคม 2569] : การกำกับดูแลบริษัทประกันภัยตามระดับความเสี่ยง;[Pillar 3] [20 พฤษภาคม 2569] : กฏหมายว่าด้วยการป้องกันและปราบปรามการฟอกเงินและต่อต้านการสนับสนุนทางการเงินแก่การก่อการร้าย;[Pillar 1] [10 มิถุนายน 2569] : การพิจารณารับประกันภัยรถยนต์;[Pillar 1] [2 กันยายน 2569] : กรมธรรม์ประกันภัยรถยนต์ไฟฟ้ารวมการคุ้มครองผู้ประสบภัยจากรถ','FChFP (Fellows Chartered Financial Practitioner) Conversion Course;สำเร็จการศึกษาตั้งแต่ระดับปริญญาโทขึ้นไป จากสถาบันอุดมศึกษาหรือสถาบันการศึกษาในต่างประเทศที่สำนักงานคณะกรรมการข้าราชการพลเรือนรับรอง;','การประกันภัยต่อ;การจัดการสินไหมทดแทน Non-Motor;การประกันความเสี่ยงภัยทรัพย์สิน;ความเสี่ยงต่อความรับผิดในฐานะตัวแทน/นายหน้าประกันภัย;การวางแผนเพื่อวัยเกษียณ',NULL,'ปริญญาโท ','บริหารความเสี่ยงและบริหารการลงทุน',NULL,10.00,'ภาคกลาง;','บริษัท เอ็มเอสไอจี ประกันภัย (ประเทศไทย) จำกัด (มหาชน);','ประกันภัยสุขภาพ;ประกันภัยสำหรับบ้านและทรัพย์สิน;',NULL,NULL,NULL,NULL