INSERT INTO `register_uat_bak` VALUES (2202,'รับทราบ','1149900431941','2028-08-06','1',NULL,'ปิยพัทธ์','','สุปุณณะ','Piyaphat','','Supunna','','','','1996-08-07','พุทธ',NULL,'B','0870528261','piyaphat5732@gmail.com','first2.7',NULL,NULL,NULL,NULL,'ประดิษฐ์ สุปุณณะ','0866062843','37/3','1',NULL,NULL,NULL,'พระนครศรีอยุธยา','บางบาล','ไทรน้อย','13250','ที่อยู่อื่น ๆ (โปรดระบุ)','159/159','2','กรีนด์โฮม',NULL,NULL,'พระนครศรีอยุธยา','พระนครศรีอยุธยา','บ้านเกาะ','13000.0','ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','ขอต่ออายุใบอนุญาตเป็น ตัวแทนหรือนายหน้า ประกันวินา','6304003378','2020-03-17','2028-03-16','ภาค 4 (ภาคกลางและภาคตะวันตก)',NULL,NULL,NULL,NULL,NULL,'พระนครศรีอยุธยา','วิริยะ','18355','นายหน้า',NULL,'ขอต่อใบอนุญาตตัวแทน/นายหน้าประกันวินาศภัย 4',NULL,NULL,NULL,NULL,NULL,NULL,'[Pillar 1] [20 พฤษภาคม 2569] : กรมธรรม์ประกันภัยรถยนต์ไฟฟ้ารวมการคุ้มครองผู้ประสบภัยจากรถ;[Pillar 2] [10 มิถุนายน 2569] : การตลาดยุคใหม่;[Pillar 1] [22 เมษายน 2569] : การกำกับดูแลบริษัทประกันภัยตามระดับความเสี่ยง','สำเร็จการศึกษาตั้งแต่ระดับปริญญาโทขึ้นไป จากสถาบันอุดมศึกษาหรือสถาบันการศึกษาในต่างประเทศที่สำนักงานคณะกรรมการข้าราชการพลเรือนรับรอง;','การวางแผนภาษีสำหรับตัวแทนและนายหน้าประกันภัย;การวางแผนเพื่อวัยเกษียณ;จรรยาบรรณและศีลธรรมของตัวแทน/นายหน้าประกันภัย;การประกันภัยต่อ;นวัตกรรมผลิตภัณฑ์ประกันวินาศภัย;พระราชบัญญัติประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต(ฉบับที่3) พ.ศ.2558',NULL,'ปริญญาโท','ขายประกัน','อยุธยา',6.00,'ภาคกลาง;','บริษัท กรุงเทพประกันภัย จำกัด (มหาชน);บริษัท เทเวศประกันภัย จำกัด (มหาชน);บริษัท เมืองไทยประกันภัย จำกัด (มหาชน);บริษัท อลิอันซ์ อยุธยา ประกันภัย จำกัด (มหาชน);บริษัท ไอโออิ กรุงเทพ ประกันภัย จำกัด (มหาชน);','ประกันภัยรถยนต์;',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-05-25 08:48:30','2026-06-22 15:54:54','ยืนยันการสมัคร','2026-01-09 15:52:50','2026-01-09 16:07:53','anonymous',NULL,NULL,NULL,NULL,NULL),(2203,'รับทราบ','1180600112711','2029-08-14','3',NULL,'ภัทรชลี','','ปั้นเนตร','patcharee','','Punnet','','','','1999-08-15','พุทธ','หญิง','B','0641965534','amzaza02@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'5','10',NULL,NULL,NULL,'ชัยนาท','หันคา','ไพรนกยูง','17130','ตรงกับที่อยู่ตามทะเบียนบ้าน',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','ขอต่ออายุใบอนุญาตเป็น ตัวแทนหรือนายหน้า ประกันวินา','6604022266',NULL,NULL,'สำนักงานใหญ่',NULL,NULL,NULL,NULL,NULL,'สุขาภิบาล3',NULL,'07154','นายหน้า',NULL,'ขอต่อใบอนุญาตนายหน้าประกันวินาศภัย 2',NULL,NULL,NULL,NULL,'1 กรกฎาคม 2569',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-05-25 08:48:30','2026-06-22 15:54:54','ยืนยันการสมัคร','2026-01-09 16:05:00','2026-01-09 16:09:00','anonymous',NULL,NULL,NULL,NULL,NULL),(2204,'รับทราบ','3800100591008','2030-10-14','3',NULL,'วรรณา','','มะลิแก้ว','wanna','','Malikaew','','','','1980-10-15','พุทธ','หญิง','B','0612128629','wanna28629@gmail.com','@na1510','วรรณา  มะลิแก้ว',NULL,'ไม่มี','ความดันสูง ไขมัน','สุนีย์  จันทร์จำปา','0805254040','19472','11',NULL,NULL,NULL,'นครศรีธรรมราช','เมือง','บางจาก','80330','ที่อยู่อื่น ๆ (โปรดระบุ)','56','14',NULL,NULL,NULL,'นครศรีธรรมราช','ท่าศาลา','โมคลาน','80160.0','ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','ขอต่ออายุใบอนุญาตเป็น ตัวแทนหรือนายหน้า ประกันวินา','6204039318','2019-09-18','2027-09-17','ภาค 5 (ภาคใต้)',NULL,NULL,NULL,NULL,NULL,'นครศรีธรรมราช',NULL,'16016','นายหน้า',NULL,'ขอต่อใบอนุญาตตัวแทน/นายหน้าประกันวินาศภัย 4',NULL,NULL,NULL,NULL,NULL,NULL,'[Pillar 1] [22 เมษายน 2569] : การกำกับดูแลบริษัทประกันภัยตามระดับความเสี่ยง;[Pillar 1] [22 เมษายน 2569] : การประกันความเสี่ยงภัยทรัพย์สิน;[Pillar 1] [22 เมษายน 2569] : การจัดการสินไหมทดแทน Non-Motor',NULL,'ธุรกิจประกันภัยไทยกับการเปิดเสรีประชาคมเศรษฐกิจอาเซียน;เสนอขายถูกหลักประกันภัยเติบโต;การวางแผนธุรกิจสำหรับตัวแทนและนายหน้าประกันภัย;การรับประกันภัยรถผ่านแดน;การพิจารณารับประกันภัยรถยนต์;ความเสี่ยงต่อความรับผิดในฐานะตัวแทน/นายหน้าประกันภัย;จรรยาบรรณและศีลธรรมของตัวแทน/นายหน้าประกันภัย;พ.ร.บ.การทวงถามหนี้;พระราชบัญญัติประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต(ฉบับที่3) พ.ศ.2558;รู้จักประกันภัยสุขภาพ;กรมธรรม์ประกันภัยรถยนต์ไฟฟ้า รวมการคุ้มครองผู้ประสบภัยจากรถ;กฎหมายและหลักการประกันภัยคุ้มครองผู้ประสบภัยจากรถ (พ.ร.บ.);พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล;หลักกฏหมายและวิธีการปฏิบัติในการประกันภัยสินค้าทางทะเล;มาตรฐานคุณภาพบริการขนส่งด้วยรถบรรทุกและการประกันภัยรถผ่านแดน',NULL,NULL,'ประกันภัย','นครศรีธรรมราช',7.00,'ภาคใต้;','บริษัท คุ้มภัยโตเกียวมารีนประกันภัย (ประเทศไทย) จำกัด;บริษัท ชับบ์สามัคคีประกันภัย จำกัด (มหาชน);บริษัท ทิพยประกันภัย จำกัด (มหาชน);บริษัท นวกิจประกันภัย จำกัด (มหาชน);บริษัท เมืองไทยประกันภัย จำกัด (มหาชน);','ประกันภัยรถยนต์;',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-05-25 08:48:30','2026-06-22 15:54:54','ยืนยันการสมัคร','2026-01-09 15:48:33','2026-01-09 16:09:37','anonymous',NULL,NULL,NULL,NULL,NULL),(2209,'รับทราบ','3100202591585','2027-02-22','2',NULL,'วรรณี ','','กรโกสียกาจ','WANNEE','','KORNKOSIYAKARJ','','','','1961-02-23','พุทธ','หญิง','A','0898315788','wanneekornko@gmail.com','0898315788','wannee vib',NULL,'ไม่','ไทรอยด์ ความดันโลหิต','กิตติ กรโกสียกาจ','0653564259','4/1','','','ประชาชื่น 9/3','','นนทบุรี','เมืองนนทบุรี','ท่าทราย','11000','ตรงกับที่อยู่ตามทะเบียนบ้าน','','','','','','','','','','ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','ขอต่อใบอนุญาตนายหน้าประกันวินาศภัย 4 เป็นต้นไป','6204042899','2019-10-02','2027-10-01','ภาค 6 (ภาคกรุงเทพฯ)',NULL,NULL,NULL,NULL,NULL,'วงศ์สว่าง','','16777','นายหน้า',NULL,'ขอต่อใบอนุญาตนายหน้าประกันวินาศภัย 4 เป็นต้นไป',NULL,NULL,NULL,NULL,NULL,NULL,'[Pillar 1] [5 สิงหาคม 2569] : การประกันความเสี่ยงภัยทรัพย์สิน;[Pillar 1] [5 สิงหาคม 2569] : การจัดการสินไหมทดแทน Non-Motor;[Pillar 1] [19 สิงหาคม 2569] : การวางแผนเพื่อวัยเกษียณ;[Pillar 1] [19 สิงหาคม 2569] : การประกันภัยต่อ;[Pillar 3] [26 สิงหาคม 2569] : จรรยาบรรณและศีลธรรมของตัวแทน/นายหน้าประกันภัย;[Pillar 1] [2 กันยายน 2569] : กรมธรรม์ประกันภัยรถยนต์ไฟฟ้ารวมการคุ้มครองผู้ประสบภัยจากรถ;[Pillar 1] [2 กันยายน 2569] : เสนอขายถูกหลักประกันภัยเติบโต;[Pillar 3] [2 กันยายน 2569] : กฏหมายว่าด้วยการป้องกันและปราบปรามการฟอกเงินและต่อต้านการสนับสนุนทางการเงินแก่การก่อการร้าย;[Pillar 3] [2 กันยายน 2569] : พ.ร.บ.การทวงถามหนี้;[Pillar 1] [9 กันยายน 2569] : การพิจารณารับประกันภัยรถยนต์;[Pillar 1] [9 กันยายน 2569] : รู้จักประกันภัยสุขภาพ;[Pillar 3] [9 กันยายน 2569] : ความเสี่ยงต่อความรับผิดในฐานะตัวแทน/นายหน้าประกันภัย',NULL,'การกำกับดูแลบริษัทประกันภัยตามระดับความเสี่ยง;พ.ร.บ.จราจรทางบก พ.ศ.2522 (แก้ไขเพิ่มเติม2562) และการพิจารณาคดีแพ่ง/อาญาเมื่อเกิดอุบัติเหตุจราจร;พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล',NULL,NULL,'-','',40.00,'ภาคกลาง',NULL,'ประกันภัยรถยนต์;ประกันภัยสำหรับบ้านและทรัพย์สิน',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-05-25 08:48:30','2026-06-22 15:54:54','ยืนยันการสมัคร','2026-01-09 15:53:26','2026-05-27 12:52:10','anonymous',NULL,NULL,NULL,NULL,NULL),(2210,'รับทราบ','1749800205880','2029-10-17','3',NULL,'กรรณิการ์ ','','จันทคัด','Kannika','','Chantakut','','','','1997-10-18','พุทธ','หญิง','O','0994576766','knkctk1810@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'120/168 ','12',NULL,NULL,NULL,'นครปฐม','สามพราน','ไร่ขิง','73210','ตรงกับที่อยู่ตามทะเบียนบ้าน',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','ขอต่อใบอนุญาตเป็น ตัวแทน ประกันวินาศภัย ครั้งที่ 1','6804008180','2025-07-11','2026-07-10','ภาค 4 (ภาคกลางและภาคตะวันตก)',NULL,NULL,NULL,NULL,NULL,'นครปฐม','บจก.ยูเอ็นที อินชัวรันส์ โบรกเกอร์','16764','นายหน้า',NULL,'ขอต่อใบอนุญาตนายหน้าประกันวินาศภัย 1',NULL,NULL,NULL,'11 มีนาคม 2569',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ภาคกลาง;ภาคตะวันตก;','บริษัท กรุงเทพประกันภัย จำกัด (มหาชน);บริษัท กรุงไทยพานิชประกันภัย จำกัด (มหาชน);บริษัท คุ้มภัยโตเกียวมารีนประกันภัย (ประเทศไทย) จำกัด;บริษัท ทิพยประกันภัย จำกัด (มหาชน);บริษัท ธนชาตประกันภัย จำกัด (มหาชน);บริษัท นวกิจประกันภัย จำกัด (มหาชน);บริษัท ประกันภัยไทยวิวัฒน์ จำกัด (มหาชน);บริษัท เมืองไทยประกันภัย จำกัด (มหาชน);บริ