INSERT INTO `register_uat_bak` VALUES (5200,'รับทราบ','1100501184161','2032-04-16','1',NULL,'ณัฐพล','','ตากรวด','Nathaphon','','Takruad','','','','1995-04-17','พุทธ','ชาย','AB','0813564768','nathaphon.ta-@turbo.co.th','-','Nathaphon Ta-Kruad','-','-','-','มยุรี ตากรวด','0894955475','26/29',NULL,'เอกวินท์ ทาวโฮม','2A','เลียบคลองสอง','กรุงเทพมหานคร','คลองสามวา','บางชัน','10510','ตรงกับที่อยู่ตามทะเบียนบ้าน',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','ขอต่ออายุใบอนุญาตเป็น ตัวแทนหรือนายหน้า ประกันวินาศภัย ครั้งที่ 4 เป็นต้นไป','6304009739','2020-10-27','2028-10-26','ภาค 3 (ภาคตะวันออก)',NULL,NULL,'พัทยา',NULL,NULL,NULL,'บริษัท เงินเทอร์โบ จำกัด (มหาชน)','16184','นายหน้า',NULL,'ขอต่อใบอนุญาตตัวแทน/นายหน้าประกันวินาศภัย 4',NULL,NULL,NULL,NULL,NULL,NULL,'[Pillar 1] [22 เมษายน 2569] : การจัดการสินไหมทดแทน Non-Motor;[Pillar 1] [22 เมษายน 2569] : การประกันความเสี่ยงภัยทรัพย์สิน;[Pillar 1] [22 เมษายน 2569] : การกำกับดูแลบริษัทประกันภัยตามระดับความเสี่ยง;[Pillar 1] [6 พฤษภาคม 2569] : การประกันภัยต่อ;[Pillar 1] [6 พฤษภาคม 2569] : การวางแผนเพื่อวัยเกษียณ;[Pillar 1] [6 พฤษภาคม 2569] : การวางแผนภาษีสำหรับตัวแทนและนายหน้าประกันภัย;[Pillar 3] [13 พฤษภาคม 2569] : จรรยาบรรณและศีลธรรมของตัวแทน/นายหน้าประกันภัย;[Pillar 3] [13 พฤษภาคม 2569] : พ.ร.บ. จราจรทางบก พ.ศ.2522 (แก้ไขเพิ่มเติม2562) และการพิจารณาคดีแพ่ง/อาญาเมื่อเกิดอุบัติเหตุจราจร;[Pillar 3] [13 พฤษภาคม 2569] :  พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล;[Pillar 1] [20 พฤษภาคม 2569] : เสนอขายถูกหลักประกันภัยเติบโต;[Pillar 3] [20 พฤษภาคม 2569] : กฏหมายว่าด้วยการป้องกันและปราบปรามการฟอกเงินและต่อต้านการสนับสนุนทางการเงินแก่การก่อการร้าย;[Pillar 1] [20 พฤษภาคม 2569] : กรมธรรม์ประกันภัยรถยนต์ไฟฟ้ารวมการคุ้มครองผู้ประสบภัยจากรถ;[Pillar 2] [10 มิถุนายน 2569] : การตลาดยุคใหม่;[Pillar 1] [10 มิถุนายน 2569] : การพิจารณารับประกันภัยรถยนต์;[Pillar 1] [10 มิถุนายน 2569] : รู้จักประกันภัยสุขภาพ;[Pillar 3] [10 มิถุนายน 2569] : ความเสี่ยงต่อความรับผิดในฐานะตัวแทน/นายหน้าประกันภัย',NULL,'การกำกับดูแลบริษัทประกันภัยตามระดับความเสี่ยง;การประกันภัยความรับผิดตามกฏหมาย;การจ่ายค่าสินไหมทดแทนประกันวินาศภัย;การวางแผนเพื่อวัยเกษียณ;การพิจารณารับประกันภัยรถยนต์;จรรยาบรรณและศีลธรรมของตัวแทน/นายหน้าประกันภัย;หลักกฏหมายและวิธีการปฏิบัติในการประกันภัยสินค้าทางทะเล;ความเสี่ยงต่อความรับผิดในฐานะตัวแทน/นายหน้าประกันภัย;กฏหมายและวิธีปฏิบัติที่เกี่ยวข้องกับธุรกิจประกันภัย;กฎหมายเบื้องต้นที่จำเป็นสำหรับชีวิตประจำวัน;พ.ร.บ. จราจรทางบก พ.ศ.2522 (แก้ไขเพิ่มเติม2562) และการพิจารณาคดีแพ่ง/อาญาเมื่อเกิดอุบัติเหตุจราจร;พระราชบัญญัติประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต(ฉบับที่3) พ.ศ.2558;พ.ร.บ.การทวงถามหนี้;กฏหมายว่าด้วยการป้องกันและปราบปรามการฟอกเงินและต่อต้านการสนับสนุนทางการเงินแก่การก่อการร้าย;การบริหารจัดการความเสี่ยงของบริษัทประกันวินาศภัยในส่วนที่เกี่ยวข้องกับการฉ้อฉล พ.ศ.2561;พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล;ประมวลกฎหมายแพ่งและพาณิชย์ว่าด้วยละเมิด;40 ถาม-ตอบหลักกฎหมายแรงงานที่ควรรู้;การพัฒนาสภาวะผู้นำของคนกลางประกันภัย;รู้จักประกันภัยสุขภาพ;การตลาดยุคใหม่;กฎหมายและหลักการประกันภัยคุ้มครองผู้ประสบภัยจากรถ (พ.ร.บ.);','อบรมต่อบัตรนายหน้าวินาศภัยครั้งที่ 4','ปริญญาตรี',NULL,'บริษัท เงินเทอร์โบ จำกัด (มหาชน)',6.00,'ภาคใต้;','บริษัท อลิอันซ์ อยุธยา ประกันภัย จำกัด (มหาชน);บริษัท แอกซ่าประกันภัย จำกัด (มหาชน);บริษัท ชับบ์สามัคคีประกันภัย จำกัด (มหาชน);','ประกันภัยรถยนต์;ประกันภัยอุบัติเหตุ;',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-05-25 08:48:30','2026-06-22 15:54:54','ยืนยันการสมัคร','2026-03-17 11:59:24','2026-03-17 12:20:14','anonymous',NULL,NULL,NULL,NULL,NULL),(5201,'รับทราบ','1141200140645','2032-08-10','3',NULL,'เสาวลักษณ์','','สุขสุทิตย์','Saowaluk','','Suksuthit','','','','1994-08-11','พุทธ','หญิง','A','0943282527','saowaluk.suk@turbo.co.th',NULL,NULL,NULL,NULL,NULL,'สมศักดิ์ สุขสุทิตย์','0870824276','16','5',NULL,NULL,NULL,'พระนครศรีอยุธยา','เสนา','บ้านแถว','13110','ตรงกับที่อยู่ตามทะเบียนบ้าน',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ใบอนุญาตเป็นนายหน้าประกันวินาศภัย','ขอต่ออายุใบอนุญาตเป็น ตัวแทนหรือนายหน้า ประกันวินาศ